<?php
namespace ZCCNG;if(!defined('ABSPATH'))exit;
final class Api{private static $instance;public static function instance(){if(!self::$instance){self::$instance=new self();add_action('rest_api_init',[self::$instance,'routes']);}return self::$instance;}public function routes(){register_rest_route('zccng/v1','/layout/(?P<workspace>[a-z0-9_-]+)',['methods'=>['GET','POST'],'callback'=>[$this,'layout'],'permission_callback'=>[$this,'can_layout']]);register_rest_route('zccng/v1','/theme',['methods'=>'POST','callback'=>[$this,'theme'],'permission_callback'=>function(){return is_user_logged_in();}]);register_rest_route('zccng/v1','/status',['methods'=>['GET','POST'],'callback'=>[$this,'status'],'permission_callback'=>function(){return is_user_logged_in()&&Permissions::instance()->workspace('staff');}]);register_rest_route('zccng/v1','/communications/inbox',['methods'=>'GET','callback'=>[$this,'communications_inbox'],'permission_callback'=>function(){return is_user_logged_in();}]);register_rest_route('zccng/v1','/communications/ticker',['methods'=>'GET','callback'=>[$this,'communications_ticker'],'permission_callback'=>function(){return is_user_logged_in();}]);register_rest_route('zccng/v1','/communications/read',['methods'=>'POST','callback'=>[$this,'communications_read'],'permission_callback'=>function(){return is_user_logged_in();}]);register_rest_route('zccng/v1','/forms',['methods'=>'GET','callback'=>[$this,'forms'],'permission_callback'=>function(){return is_user_logged_in();}]);register_rest_route('zccng/v1','/candidate',['methods'=>'GET','callback'=>[$this,'candidate'],'permission_callback'=>function(){return is_user_logged_in();}]);register_rest_route('zccng/v1','/clock',['methods'=>['GET','POST'],'callback'=>[$this,'clock'],'permission_callback'=>function(){return is_user_logged_in()&&Permissions::instance()->workspace('staff');}]);}public function can_layout($r){$w=sanitize_key($r['workspace']);return is_user_logged_in()&&Permissions::instance()->known_workspace($w)&&Permissions::instance()->workspace($w)&&Permissions::instance()->can('zccng_manage_layouts');}public function layout($r){global $wpdb;$t=$wpdb->prefix.'zccng_layouts';$u=get_current_user_id();$w=sanitize_key($r['workspace']);if($r->get_method()==='GET'){$raw=$wpdb->get_var($wpdb->prepare("SELECT layout FROM $t WHERE user_id=%d AND workspace=%s",$u,$w));$layout=$raw?json_decode($raw,true):[];return rest_ensure_response(['layout'=>is_array($layout)?$layout:[]]);}$body=$r->get_json_params();$layout=$body['layout']??[];if(!is_array($layout))return new \WP_Error('invalid_layout','Invalid layout',['status'=>400]);$clean=array_slice(array_values(array_unique(array_map('sanitize_key',$layout))),0,100);$ok=$wpdb->replace($t,['user_id'=>$u,'workspace'=>$w,'layout'=>wp_json_encode($clean),'updated_at'=>current_time('mysql')],['%d','%s','%s','%s']);if($ok===false)return new \WP_Error('save_failed','Layout could not be saved.',['status'=>500]);Audit::log('layout_saved','Saved '.ucwords(str_replace('_',' ',$w)).' layout',['workspace'=>$w]);return ['saved'=>true];}public function theme($r){$allowed=['celestial-midnight','nebula-glass','quantum-command','celestial-daylight','cloud-nexus','solar-command'];$body=$r->get_json_params();$theme=sanitize_key($body['theme']??'');if(!in_array($theme,$allowed,true))return new \WP_Error('invalid_theme','Invalid theme',['status'=>400]);update_user_meta(get_current_user_id(),'zccng_theme',$theme);Audit::log('theme_changed','Theme changed',['theme'=>$theme]);return ['theme'=>$theme];}public function clock($r){global $wpdb;$u=get_current_user_id();$t=$wpdb->prefix.'zccng_time_entries';if($r->get_method()==='GET')return $this->clock_state($u);$body=$r->get_json_params();$action=sanitize_key($body['action']??'');$open=$wpdb->get_row($wpdb->prepare("SELECT * FROM $t WHERE user_id=%d AND status='open' ORDER BY id DESC LIMIT 1",$u),ARRAY_A);if($action==='clock_in'){if($open)return new \WP_Error('already_clocked_in','Already clocked in.',['status'=>409]);if($wpdb->insert($t,['user_id'=>$u,'clock_in_gmt'=>current_time('mysql',true),'status'=>'open'],['%d','%s','%s'])===false)return new \WP_Error('clock_failed','Clock-in failed.',['status'=>500]);update_user_meta($u,'zcc_clock_status','clocked_in');Audit::log('clock_in','Shift started');}elseif($action==='clock_out'){if(!$open)return new \WP_Error('not_clocked_in','Not clocked in.',['status'=>409]);$seconds=max(0,time()-strtotime($open['clock_in_gmt'].' UTC'));if($wpdb->update($t,['clock_out_gmt'=>current_time('mysql',true),'total_seconds'=>$seconds,'status'=>'closed'],['id'=>(int)$open['id']],['%s','%d','%s'],['%d'])===false)return new \WP_Error('clock_failed','Clock-out failed.',['status'=>500]);update_user_meta($u,'zcc_clock_status','clocked_out');Audit::log('clock_out','Shift ended',['total_seconds'=>$seconds]);}else return new \WP_Error('invalid_action','Invalid clock action.',['status'=>400]);update_user_meta($u,'zcc_last_seen',time());return $this->clock_state($u);}public function status($r){$u=get_current_user_id();$allowed=['available','busy','in_meeting','on_break','offline'];if($r->get_method()==='GET')return ['status'=>get_user_meta($u,'zcc_availability_status',true)?:'available'];$body=$r->get_json_params();$status=sanitize_key($body['status']??'');if(!in_array($status,$allowed,true))return new \WP_Error('invalid_status','Invalid availability status.',['status'=>400]);update_user_meta($u,'zcc_availability_status',$status);Audit::log('status_changed','Availability changed',['status'=>$status]);return ['status'=>$status];}public function communications_inbox(){return Communications::inbox(get_current_user_id(),50);}public function communications_ticker(){return Communications::active_ticker();}public function communications_read($r){global $wpdb;$id=absint(($r->get_json_params())['broadcast_id']??0);if(!$id)return new \WP_Error('invalid_broadcast','Invalid broadcast.',['status'=>400]);$t=$wpdb->prefix.'zccng_message_reads';$wpdb->replace($t,['broadcast_id'=>$id,'user_id'=>get_current_user_id(),'read_at'=>current_time('mysql',true)],['%d','%d','%s']);return ['read'=>true];}public function candidate(){return Candidates::get(get_current_user_id())?:new \WP_Error('not_candidate','Candidate profile not found.',['status'=>404]);}public function forms(){return Forms::assignments(get_current_user_id());}private function clock_state($u){global $wpdb;$t=$wpdb->prefix.'zccng_time_entries';$open=$wpdb->get_row($wpdb->prepare("SELECT clock_in_gmt FROM $t WHERE user_id=%d AND status='open' ORDER BY id DESC LIMIT 1",$u),ARRAY_A);$today=(int)$wpdb->get_var($wpdb->prepare("SELECT COALESCE(SUM(total_seconds),0) FROM $t WHERE user_id=%d AND status='closed' AND DATE(clock_in_gmt)=UTC_DATE()",$u));$week=(int)$wpdb->get_var($wpdb->prepare("SELECT COALESCE(SUM(total_seconds),0) FROM $t WHERE user_id=%d AND status='closed' AND YEARWEEK(clock_in_gmt,1)=YEARWEEK(UTC_DATE(),1)",$u));$last=(int)$wpdb->get_var($wpdb->prepare("SELECT COALESCE(total_seconds,0) FROM $t WHERE user_id=%d AND status='closed' ORDER BY clock_out_gmt DESC LIMIT 1",$u));return ['status'=>$open?'clocked_in':'clocked_out','clock_in_gmt'=>$open?$open['clock_in_gmt']:null,'today_seconds'=>$today,'week_seconds'=>$week,'last_shift_seconds'=>$last];}}
